def calculate_total(price, taxable=False, discount=False):
    if taxable and discount:
        return round(price * 1.2 * 0.9, 2)
    if taxable:
        return round(price * 1.2, 2)
    if discount:
        return round(price * 0.9, 2)
    return round(price, 2)

